# Tổng cộng 35 entry (câu 6–40): 19 choice (6–17 phát âm/từ vựng/ngữ pháp, 23–24 tìm lỗi, 25–29 đọc hiểu), 10 fill (18–22 word form, 30–34 cloze), 6 essay (35–40 viết lại câu, 3 dòng). 0 hình.
# Khác bản cũ _DE_5: (1) Câu 24 — bản cũ ghi option C là “buy (C)”, nhìn ảnh trang thì phần gạch chân là “to buy (C)” → sửa lại. (2) Câu 23–24: option bỏ hậu tố “(A)/(B)…” thừa, chỉ giữ từ/cụm gạch chân. (3) Câu 35–40 (viết lại câu): bản cũ dùng type fill (bắt gõ nguyên câu, so khớp chính xác) → nay chuyển essay 3 dòng, đáp án mẫu nằm trong explanation. (4) Câu 20: thêm alt_answers “colored” (chính tả Mỹ). (5) Explanation viết lại đầy đủ (quy tắc, nghĩa từ, IPA, dịch câu) thay vì chú thích ngắn; bỏ ghi chú thừa “(Viết lại cả câu như đáp án.)” trong hướng dẫn phần VIII. Các câu còn lại (6–17, 18–22, 25–34) đối chiếu từng chữ với PDF: không phát hiện chép sai ở bản cũ.
# Câu 6–9 (phát âm): PDF mất gạch chân → xác định từ ảnh trang 1: câu 6 chữ e; câu 7 chữ ch; câu 8 chữ o; câu 9 đuôi -ed. Phần gạch chân đánh dấu trong ngoặc đơn.
# Câu 23: đáp án gốc A (are → aren’t). Cũng có thể sửa “any” → “some” nhưng “any” không được gạch chân/đánh (A–D) nên chỉ chấp nhận A. Câu 23–24 là dạng tìm lỗi (chọn A/B/C/D) — phần sửa lỗi nằm trong explanation.
# Câu nghi ngờ (không đổi đáp án): câu 31 — “eggs” cũng đúng ngữ pháp (bought the eggs) nhưng đáp án gốc là “ingredients” (hợp với “recipe”, “flour, salt, water”) nên giữ “ingredients”; câu 26 — người viết học tiếng Tây Ban Nha ở trường THPT và hiện vẫn học ở đại học, đáp án gốc B (at high school) vẫn là lựa chọn duy nhất khớp với các phương án.
